// TGP profiling: where the recompiled TGP program's time goes. Built only
// with M2_TGP_PROFILE (scripts/recompile.py --tgp-profile, CMake
// -DM2_TGP_PROFILE=ON; scripts/build_vita.py --tgp-profile, written to
// perf.log), which also needs TGP code generated by m2tgprecomp --profile.
// Without it the runtime and the generated code are unchanged.
//
// What it measures:
//   - time: every TgpBoard::run_tgp call is timed with the frontend's clock
//     (the Vita's is in microseconds), minus the clock's own cost measured at
//     start; with the number of calls, instructions, ns and cycles per
//     instruction;
//   - work: m2tgprecomp --profile counts the executions of each basic block
//     (one increment at its end) and writes what each block holds
//     (TgpBlockInfo); executions x contents = FIFO words, table and banked
//     accesses, data RAM accesses, floating-point operations by kind,
//     branches, dispatches. The runtime counts which table port and which
//     bank each I/O access reached;
//   - unit costs on the host (tgp_microbench): ns per floating-point mul+add,
//     divide, float-to-int rounding, table read, banked read, FIFO word, so
//     the report can give an estimated time per kind and what it leaves
//     unexplained (dispatch, straight-line loads and stores, branches);
//   - the hottest blocks of the window.
// Counters never change what the TGP computes.
#pragma once

#include <cstddef>
#include <cstdint>

namespace rt {

// What a basic block of the TGP program holds, counted per instruction by
// m2tgprecomp --profile (always defined: the recompiler uses it too).
enum TgpOp : uint8_t {
    TgpOpFifoIn,    // input FIFO word read (register 0x21)
    TgpOpFifoOut,   // output FIFO word written (register 0x22)
    TgpOpBankW,     // bank register write (0x23)
    TgpOpIoR,       // I/O read: table port or banked memory (Tgp::io_r)
    TgpOpIoW,       // I/O write: table base or banked memory (Tgp::io_w)
    TgpOpDataR,     // data RAM read
    TgpOpDataW,     // data RAM write
    TgpOpProgR,     // program RAM read
    TgpOpFpAdd,     // ALU float add/subtract
    TgpOpFpMul,     // ALU float multiply
    TgpOpFpDiv,     // ALU float divide (0x10)
    TgpOpFpToInt,   // ALU float to integer with roundf/ceilf/floorf (0x0f)
    TgpOpIntToFp,   // ALU integer to float (0x0e)
    TgpOpIntAlu,    // ALU integer, logic, shift, abs/neg
    TgpOpBranch,    // conditional or constant branch, ldif
    TgpOpComputed,  // branch to a computed address (through the dispatch switch)
    TgpOpRep,       // rep
    kTgpOps
};

struct TgpBlockInfo {
    uint16_t start, length;   // first word, instructions
    uint8_t ops[kTgpOps];     // per execution of the block
};

} // namespace rt

#ifdef M2_TGP_PROFILE

#include <vector>

namespace rt {

class TgpBoard;

struct TgpProfile {
    uint64_t (*clock)() = nullptr; // host ticks (set by the frontend); null: no timing
    uint64_t ticks_per_second = 1000000;
    uint64_t runs = 0, empty_runs = 0, ticks = 0;
    // Tgp::io_r / io_w by target, TgpBoard::mem_r / mem_w by bank.
    uint64_t table_r[4]{};   // sin/cos, atan, 1/x, 1/sqrt ports
    uint64_t table_w = 0, io_unmapped = 0;
    uint64_t bank_r_rom = 0, bank_r_buffer = 0, bank_r_none = 0, bank_w = 0;
};
extern TgpProfile tgp_profile;

namespace tgpgen { // m2tgprecomp --profile
extern const TgpBlockInfo blocks[];
extern const uint32_t block_count;
extern uint64_t block_hits[];
extern uint64_t dispatches; // run entries + computed branches
} // namespace tgpgen

// Host cost of the TGP's primitive operations, in ns each (tgp_microbench).
struct TgpBench {
    bool done = false;
    double clock_ns = 0;       // one clock read (the bias removed from each timed run)
    double loop_ns = 0;        // the benchmark loop alone (removed from the others)
    double fp_muladd_ns = 0;   // ALU 0x09: d + p and a * b, dependent
    double fp_div_ns = 0;      // ALU 0x10
    double fp_round_ns = 0;    // ALU 0x0f: roundf + conversion
    double table_r_ns = 0;     // Tgp::io_r on the sin/cos port
    double bank_rom_ns = 0;    // TgpBus::mem_r on the copro data ROM (virtual call)
    double bank_buffer_ns = 0; // TgpBus::mem_r on buffer RAM
    double fifo_ns = 0;        // one word pushed and popped
};
// About 0.1 s; read-only on the board (banked reads only).
TgpBench tgp_microbench(TgpBoard &board);

// The report of one window: start() at its beginning, format() at its end.
class TgpProfileReport {
public:
    void start(uint64_t tgp_instructions);
    // frames: emulated frames in the window; cpu_mhz: for cycles (0: none);
    // whole_ms: a frontend time per frame that contains the TGP's, named by
    // whole (null: none).
    size_t format(char *out, size_t size, uint64_t frames, uint64_t tgp_instructions, int cpu_mhz, double whole_ms,
                  const char *whole, const TgpBench &bench) const;
    // The TGP's time per frame in the window, clock reads removed (the i960
    // report takes it out of gen::run's).
    double ms_per_frame(uint64_t frames, const TgpBench &bench) const;

private:
    TgpProfile at_{};
    uint64_t instructions_ = 0, dispatches_ = 0;
    std::vector<uint64_t> hits_;
    mutable std::vector<uint32_t> order_;
};

} // namespace rt

#endif // M2_TGP_PROFILE
